    function initDB() {
        const dbVersion = 2;
        const request = indexedDB.open("BlockComposer", dbVersion);
        request.onerror = (event) => {
            console.error("Database error: " + event.target.error);
        };
        request.onupgradeneeded = (event) => {
            db = event.target.result;

            if(event.oldVersion < dbVersion) {
                let names = db.objectStoreNames;
                if(names.length > 0 && names.contains("audio")) db.deleteObjectStore("audio");
                if(names.length > 0 && names.contains("images")) db.deleteObjectStore("images");    
            }
            db.createObjectStore("audio", { keyPath: "name" });
            db.createObjectStore("images", { keyPath: ["name", "uid"] });
        };
        request.onsuccess = (event) => {
            db = event.target.result;
            setSpineImage();
            setSpineAudio();
        };
    }

    function setSpineImage() {
        const img_list = new Map([]);
        const image_DB = db.transaction(["images"], "readwrite").objectStore("images");
        const request = image_DB.getAll();
        request.onsuccess = (event) => {
            const result = event.target.result;
            const images = getItemComposer()?.worldModel?.options?.images;
            if(images) {
                images.forEach(d => {
                   let data = result.find(r => r?.name == d.name && r?.uid == d.uid);
                   if(data) img_list.set(d.name, data.data);
                });
            }
            else {
                image_DB.clear();
            }
        };
        spine_images = img_list;
    }

    function setSpineAudio() {
        const audio_list = new Map([]);
        const audio_DB = db.transaction(["audio"], "readwrite").objectStore("audio");
        const request = audio_DB.getAll();
        request.onsuccess = (event) => {
            const result = event.target.result;
            const audios = getItemComposer()?.audio;
            if(audios) {
                audios.forEach(d => {
                   let data = result.find(r => r?.name == d.name);
                   if(data) audio_list.set(d.name, data.wav);
                });
            }
            else {
                audio_DB.clear();
            }
        };
        spine_audio = audio_list;
    }

