        "script": "// put code here, to setup   \nasync function setup() {\n    const ASR = new (window.SpeechRecognition || window.webkitSpeechRecognition);\n    ASR.onstart = () => { $('state').d = 1; }\n    ASR.onend = () => { $('state').d = 0; }\n    ASR.onresult = async (e) => {\n        $('result').d = e.results[0][0].transcript || '';\n        $('state').d = 0;\n        $('!listen').e = spine.ev.listen;\n        \n        ASR.abort();\n    }\n    spine.ASR = ASR;\n    spine.ev = {};\n}\n\n// put code here, to handle motor data   \nfunction serialize() {\n    spine.ev.listen = spine.ev.listen === undefined ? 0 : spine.ev.listen;\n    \n    if(spine.ev.listen !== $('listen').c) {\n        spine.ev.listen = $('listen').c;\n        \n        const ASR = spine.ASR;\n        if($('listen').d) ASR.start();\n        else ASR.abort();\n    }\n}\n\n// put code here, to handle sensory data   \nfunction deserialize() {\n}\n\n// put code here, to extend sensory data\nfunction sensory() {\n}\n\n// put code here, to extend motor data\nfunction motor() {\n}\n\n// put control code here, to run repeatedly\nfunction reflex() {\n}\n\n// put code here, to display dashboard panel\nfunction dashboard() {\n    w2popup.resize(520, 320);\n    window.onresize = () => {\n        w2popup.resize(520, 320);\n    }\n    \n    const popup_box = select('#dashboard');\n    popup_box.style('user-select', 'none');\n    \n    const photo_frame = popup_box.append('svg')\n        .attr(\"width\", 500)\n        .attr(\"height\", 250);\n    \n    let screen = photo_frame.append('g')\n        .attr(\"width\", 370)\n        .attr(\"height\", 70)\n        .attr(\"transform\", \"translate(70, 20)\");\n    screen.append('rect')\n        .attr(\"width\", 370)\n        .attr(\"height\", 70)\n        .attr(\"rx\", 5)\n        .attr(\"ry\", 5)\n        .style(\"fill\", \"lightgray\")\n        .style(\"opacity\", .5);\n    screen.append('text')\n        .attr(\"id\", \"ASR_text\")\n        .attr(\"x\", 185)\n        .attr(\"y\", 35)\n        .attr(\"font-size\", \"16px\")\n        .attr(\"text-anchor\", \"middle\")\n        .attr(\"alignment-baseline\", \"middle\")\n        .style(\"fill\", \"gray\")\n        .text(\"Select a language and click the button\");\n    \n    let langSelect = photo_frame.append('g')\n        .attr(\"width\", 150)\n        .attr(\"height\", 30)\n        .attr(\"transform\", \"translate(175, 110)\");\n    langSelect.append('foreignObject')\n        .attr(\"width\", 150)\n        .attr(\"height\", 30)\n        .html(function (d) {\n            return '<select id=\"ASR_lang\" name=\"languages\" style=\"width:150px; height:30px;\">' + \n                    '<option value=\"ko-KR\" selected>ko-KR (한글)</option>' + \n                    '<option value=\"en-US\">en-US (영어)</option>' + \n                    '<option value=\"ja-JP\">ja-JP (일본어)</option>' + \n                    '<option value=\"zh-CN\">zh-CN (중국어)</option>' + \n                    '</select>';\n        });\n\n    let rec = photo_frame.append('g')\n        .attr(\"id\", \"ASR_record\")\n        .attr(\"width\", 150)\n        .attr(\"height\", 50)\n        .attr(\"transform\", \"translate(250, 200)\")\n        .style(\"cursor\", \"pointer\");\n    rec.append('circle')\n        .attr(\"r\", 24)\n        .attr(\"x\", 50)\n        .attr(\"y\", 0)\n        .style(\"fill\", \"red\");\n}\n\n// put draw code here, to run repeatedly\nfunction control() {\n    $('lang').d = select('#ASR_lang').property(\"value\");\n    select('#ASR_record').on('click', function() {\n        $('listen').d = ($('state').d ^ 0x01);  // if state == 0, listen;  if state == 1, abort;\n    })\n    \n    let rec = select('#ASR_record');\n    if($('listen').d === 1 && $('state').d === 0) {\n        rec.selectAll('circle').remove();\n        rec.append('rect')\n            .attr(\"width\", 50)\n            .attr(\"height\", 50)\n            .attr(\"rx\", 5)\n            .attr(\"ry\", 5)\n            .attr(\"transform\", \"translate(-25, -25)\")\n            .style(\"fill\", \"red\");\n        select('#ASR_text')\n            .style(\"fill\", \"red\")\n            .text(\"Listening...\");\n    }\n    else if(($('listen').d === 0 && $('state').d === 1) || $('!listen').e) {\n        rec.selectAll('rect').remove();\n        rec.append('circle')\n            .attr(\"r\", 24)\n            .attr(\"x\", 50)\n            .attr(\"y\", 0)\n            .style(\"fill\", \"red\");\n        select('#ASR_text')\n            .style(\"fill\", \"gray\")\n            .text(\"Select the language and Click the button\");\n    }\n    \n    if($('!listen').e) {\n        select('#ASR_text').text($('result').d);\n        rec.selectAll('rect').remove();\n        rec.append('circle')\n            .attr(\"r\", 24)\n            .attr(\"x\", 50)\n            .attr(\"y\", 0)\n            .style(\"fill\", \"red\");\n            \n        $('listen').d = 0;\n    }\n}\n\n// put code here, to display sketch panel\nfunction sketch() {\n/*  Uncomment code here, to create new custom popup\n    const options = {};\n    w2custompopup.open(options);\n*/   \n    let pCanvas = new p5((p) => {\n        p.setup = function () {\n            psetup(p);\n        };\n        p.draw = () => {\n            pdraw(p);\n        };\n    }, \"p5-canvas\");\n}\n\n// put setup code here, to setup panel\nfunction psetup(p) {\n}\n\n// put draw code here, to run repeatedly\nfunction pdraw(p) {\n}\n\nfunction play() {\n    return [setup, serialize, deserialize, sensory, motor, reflex, dashboard, control, sketch]; \n};\nplay();\n",
