rt('https://cdn.jsdelivr.net/npm/@tensorflow/tfjs-backend-cpu');  // @tensorflow/tfjs-backend-cpu  \n        })\n        .then(() => {\n            return import('https://cdn.jsdelivr.net/npm/@mediapipe/hands')\n        })\n        .then(() => {\n            this._mpHands = globalThis.Hands;\n            return import('https://cdn.jsdelivr.net/npm/@tensorflow-models/hand-pose-detection');\n        })\n        .then(() => {\n            this._handDetection = globalThis.handPoseDetection;\n        })\n        .catch(err => console.error(err));\n    }\n    \n    __wait(n) {\n        return new Promise(r => setTimeout(r, n));\n    }\n    \n    async requestCamera() {\n        try {\n            const permission = await navigator.permissions.query({ name: 'camera' });\n            if(permission.state === 'granted' || permission.state === 'denied') return;\n\n            const stream = await navigator.mediaDevices.getUserMedia({ video: true });\n            stream.getTracks().forEach(track => track.stop());\n        } catch (err) {\n            console.error(err);\n            return false;\n        }\n    }\n    \n    async _createDetector(maxHands) {\n        while(!this._handDetection) await this.__wait(1);\n        \n        return this._handDetection.createDetector(this._handDetection.SupportedModels.MediaPipeHands, {\n            runtime: 'mediapipe',\n\t\t\tmodelType: 'full',\n\t\t\tmaxHands: maxHands || this._maxHands,\n\t\t\tsolutionPath: `https://cdn.jsdelivr.net/npm/@mediapipe/hands`  // hands@${this._mpHands.VERSION}\n        })\n    }\n\t\n\t_onResult(results) {\n\t\tif(results && results.length > 0) {\n\t\t\tthis._detected = true;\n\t\t\tconst halfWidth = $('camera.width').d / 2;  // ai_videoManager.getVideoWidth()\n\t\t\tconst halfHeight = $('camera.height').d / 2;  // ai_videoManager.getVideoHeight()\n\t\t\tlet keypoints = results[0].keypoints.map(pt => {\n\t\t\t\tpt.x = parseInt(pt.x * $('camera.scale.width').d);\n\t\t\t\tpt.y = parseInt(pt.y * $('camera.scale.height').d);\n\t\t\t\treturn pt;\n\t\t\t});\n\t\t\tif(this._maxHands == 1) {\n\t\t\t\tthis._setData(this._data.left, keypoints, halfWidth, halfHeight);\n\t\t\t\tthis._setData(this._data.right, keypoints, halfWidth, halfHeight);\n\t\t\t\tthis._setValues(this._values.left, keypoints, halfWidth, halfHeight);\n\t\t\t\tthis._setValues(this._values.right, keypoints, halfWidth, halfHeight);\n\t\t\t} else {\n\t\t\t\tif(results[0].handedness == 'Left') {\n\t\t\t\t\tthis._setData(this._data.left, keypoints, halfWidth, halfHeight);\n\t\t\t\t\tthis._setValues(this._values.left, keypoints, halfWidth, halfHeight);\n\t\t\t\t} else {\n\t\t\t\t\tthis._setData(this._data.right, keypoints, halfWidth, halfHeight);\n\t\t\t\t\tthis._setValues(this._values.right, keypoints, halfWidth, halfHeight);\n\t\t\t\t}\n\t\t\t\tif(results.length > 1) {\n\t\t\t\t\tkeypoints = results[1].keypoints.map(pt => {\n\t\t\t\t\t\tpt.x *= $('camera.scale.width').d;\n\t\t\t\t\t\tpt.y *= $('camera.scale.height').d;\n\t\t\t\t\t\treturn pt;\n\t\t\t\t\t});\n\t\t\t\t\tif(results[1].handedness == 'Left') {\n\t\t\t\t\t\tthis._setData(this._data.left, keypoints, halfWidth, halfHeight);\n\t\t\t\t\t\tthis._setValues(this._values.left, keypoints, halfWidth, halfHeight);\n\t\t\t\t\t} else {\n\t\t\t\t\t\tthis._setData(this._data.right, keypoints, halfWidth, halfHeight);\n\t\t\t\t\t\tthis._setValues(this._values.right, keypoints, halfWidth, halfHeight);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tthis._setFeature();\n\t\t\tthis.drawFrame();\n\t\t} else {\n\t\t\tthis._detected = false;\n\t\t\tthis._clearData();\n\t\t\tthis._clearValues();\n\t\t\tthis._featureVector = [];\n\t\t\tthis._featureString = '';\n\t\t}\n\t\tthis._results = results;\n\t}\n\t\n\t_setData(data, keypoints, halfWidth, halfHeight) {\n\t\tdata.wrist[0].x = parseInt(keypoints[0].x - halfWidth);\n\t\tdata.wrist[0].y = parseInt(halfHeight - keypoints[0].y);\n\t\tlet finger = data.thumb, index = 1;\n\t\tfor(let i = 0; i < 4; ++i) {\n\t\t\tfinger[i].x = parseInt(keypoints[index].x - halfWidth);\n\t\t\tfinger[i].y = parseInt(halfHeight - keypoints[index].y);\n\t\t\t++index;\n\t\t}\n\t\tfinger = data.index;\n\t\tfor(let i = 0; i < 4; ++i) {\n\t\t\tfinger[i].x = parseInt(keypoints[index].x - halfWidth);\n\t\t\tfinger[i].y = parseInt(halfHeight - keypoints[index].y);\n\t\t\t++index;\n\t\t}\n\t\tfinger = data.middle;\n\t\tfor(let i = 0; i < 4; ++i) {\n\t\t\tfinger[i].x = parseInt(keypoints[index].x - halfWidth);\n\t\t\tfinger[i].y = parseInt(halfHeight - keypoints[index].y);\n\t\t\t++index;\n\t\t}\n\t\tfinger = data.ring;\n\t\tfor(let i = 0; i < 4; ++i) {\n\t\t\tfinger[i].x = parseInt(keypoints[index].x - halfWidth);\n\t\t\tfinger[i].y = parseInt(halfHeight - keypoints[index].y);\n\t\t\t++index;\n\t\t}\n\t\tfinger = data.pinky;\n\t\tfor(let i = 0; i < 4; ++i) {\n\t\t\tfinger[i].x = parseInt(keypoints[index].x - halfWidth);\n\t\t\tfinger[i].y = parseInt(halfHeight - keypoints[index].y);\n\t\t\t++index;\n\t\t}\n\t\tlet x = 0, y = 0;\n\t\tfor(const i in this._PALMS) {\n\t\t\tindex = this._PALMS[i];\n\t\t\tx += keypoints[index].x - halfWidth;\n\t\t\ty += halfHeight - keypoints[index].y;\n\t\t}\n\t\tdata.palm[0].x = parseInt(x / this._PALMS.length);\n\t\tdata.palm[0].y = parseInt(y / this._PALMS.length);\n\t}\n\t\n\t_setValues(values, keypoints, halfWidth, halfHeight) {\n\t\tthis._calcValues(values.hand, keypoints, halfWidth, halfHeight);\n\t\tthis._calcValues(values.palm, keypoints, halfWidth, halfHeight, this._PALMS);\n\t}\n\t\n\t_calcValues(values, keypoints, halfWidth, halfHeight, indices) {\n\t    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity, pt;\n\t\tif(indices) {\n\t\t\tfor(const i in indices) {\n\t\t\t\tpt = keypoints[indices[i]];\n\t\t\t\tif(pt.x < minX) minX = pt.x;\n\t\t\t\tif(pt.x > maxX) maxX = pt.x;\n\t\t\t\tif(pt.y < minY) minY = pt.y;\n\t\t\t\tif(pt.y > maxY) maxY = pt.y;\n\t\t\t}\n\t\t} else {\n\t\t\tfor(const i in keypoints) {\n\t\t\t\tpt = keypoints[i];\n\t\t\t\tif(pt.x < minX) minX = pt.x;\n\t\t\t\tif(pt.x > maxX) maxX = pt.x;\n\t\t\t\tif(pt.y < minY) minY = pt.y;\n\t\t\t\tif(pt.y > maxY) maxY = pt.y;\n\t\t\t}\n\t\t}\n\t\tvalues.tlx = parseInt(minX - halfWidth);\n\t\tvalues.tly = parseInt(halfHeight - maxY);\n\t\tvalues.brx = parseInt(maxX - halfWidth);\n\t\tvalues.bry = parseInt(halfHeight - minY);\n\t\tvalues.width = Math.abs(values.brx - values.tlx);\n\t\tvalues.height = Math.abs(values.bry - values.tly);\n\t\tvalues.area = values.width * values.height;\n\t}\n\t\n\t_setFeature() {\n\t\tconst vector = [];\n\t\tconst left = this._data.left;\n\t\tconst right = this._data.right;\n\t\t\n\t\tlet x = left.wrist[0].x;\n\t\tlet y = left.wrist[0].y;\n\t\tlet width = this._values.left.palm.width;\n\t\tlet height = this._values.left.palm.height;\n\t\tif(width === 0 || height === 0) {\n\t\t\tfor(let i = 0; i < 40; ++i) {\n\t\t\t\tvector.push(0);\n\t\t\t}\n\t\t} else {\n\t\t\tvector.push((left.thumb[3].x - x) / width);\n\t\t\tvector.push((left.thumb[3].y - y) / height);\n\t\t\tvector.push((left.thumb[2].x - x) / width);\n\t\t\tvector.push((left.thumb[2].y - y) / height);\n\t\t\tvector.push((left.thumb[1].x - x) / width);\n\t\t\tvector.push((left.thumb[1].y - y) / height);\n\t\t\tvector.push((left.thumb[0].x - x) / width);\n\t\t\tvector.push((left.thumb[0].y - y) / height);\n\t\t\tvector.push((left.index[3].x - x) / width);\n\t\t\tvector.push((left.index[3].y - y) / height);\n\t\t\tvector.push((left.index[2].x - x) / width);\n\t\t\tvector.push((left.index[2].y - y) / height);\n\t\t\tvector.push((left.index[1].x - x) / width);\n\t\t\tvector.push((left.index[1].y - y) / height);\n\t\t\tvector.push((left.index[0].x - x) / width);\n\t\t\tvector.push((left.index[0].y - y) / height);\n\t\t\tvector.push((left.middle[3].x - x) / width);\n\t\t\tvector.push((left.middle[3].y - y) / height);\n\t\t\tvector.push((left.middle[2].x - x) / width);\n\t\t\tvector.push((left.middle[2].y - y) / height);\n\t\t\tvector.push((left.middle[1].x - x) / width);\n\t\t\tvector.push((le