    const separators = {"roboid": ":", "slot": ">", "module": "+", "unit": ".", "audio": ".",};

    function getItemComposer(){
       let composer = localStorage.getItem("BlockComposer");
       if(composer) return JSON.parse(composer);

       // init localStorage
       composer = {"options":{}, "workspace": {},};  // "roboids":[], "world":{}, "composer": {}
       setItemComposer(composer);
       return composer;  // {}
    }

    function setItemComposer(composer) {
       localStorage.setItem("BlockComposer", JSON.stringify(composer));
    }

    function emptyWorld(name) {
       const composer = getItemComposer();
       let worldModel = {"options": {}, "imported_roboids": [], "world": {}};
       let world = {
           "class": "world",
           "creator": "robomation",
           "name": name,
           "uid": name + "-robomation-0",
           "version": "0"
       };
       let organs = [{"urn": "_", ...world}];
       let model = {"items": [], ...world};
       world.organs = organs;
       world.model = model;
       worldModel.world = world;
       composer.worldModel = worldModel;
       setItemComposer(composer);
       return worldModel;
    }

    async function importRoboid(name) {
       // const roboid_name = roboids[name] || extensions[name];
       // const response = await fetch(`https://market.roboid.org/api/post/download?filename=Roboid/${roboid_name}.roboid`, {
       //    method: 'GET',
       //    headers: {
       //          'Content-Type': 'application/json'
       //    }
       // })
       // const blob = await response.blob();
       // const roboid_model = await compressZip(blob);

       const roboid_model = roboids[name] || extensions[name];
       const roboid = roboid_model.roboid;
       const { implement, uid } = roboid;

       const composer = getItemComposer();
       let world_model = composer?.worldModel;  
       
       // if worldModel does not exist, create empty world
       if(!world_model) {
          world_model = emptyWorld(implement);
          composer.workspace = new_workspace[world_model.world.name];
       }
       
       const world = world_model.world;
       let model = world.model;

       // if trying to import multiple extension, return
       // if(Object.keys(extensions).includes(name) && world_model.imported_roboids.find(r => r.uid === roboid.uid)) 
       //    return;

       // 1. append roboid to imported_roboids list
       if(!world_model.imported_roboids.find(r => r.uid === roboid.uid))
          world_model.imported_roboids.push(roboid);
       
       // 2. append organised roboid to world-model-items
       model.items.push({ "class": "roboid", "name": implement, "uid": uid });

       // 3. merge world
       model = mergeWorld(model, world_model.imported_roboids);
       world.model = model;

       // 4. flatten? merge? organs
       world.organs = flattenWorld(world.model);
       world_model.world = world;

       // 5. set worldModel options
       const { lang, images } = roboid_model.options;
       
       const options = world_model.options;
       options.images = options.images === undefined ? [] : options.images;
       if(images) {
          const image_DB = db.transaction(["images"], "readwrite").objectStore("images");
          images.forEach(img => {
             img.uid = uid;
             if(!options.images.find(d => d?.name == img.name && d?.uid == img.uid)) {
                image_DB.add(img);
                delete img.data;
                options.images.push(img);
             }
             else {
                image_DB.put(img);
             }
          });
       }
       world_model.options = options;
       composer.worldModel = world_model;
       
       // const workspace = JSON.stringify(composer.workspace);
       // if(!workspace.includes(composer.worldModel.world.name))  // if code does not includes valid robot block, reset the world
       //    composer.workspace = new_workspace[composer.worldModel.world.name];
       setItemComposer(composer);
       // location.reload();
    }

    function processModelFile(file) {
       const reader = new FileReader();
       reader.onload = function () {  // restore session
             let composer = JSON.parse(reader.result);
             composer = processAudio(composer);
             processRoboids(composer);
       };
       try {
             JSZip.loadAsync(file)
             .then(z => {
                let zfile;
                for(let zobj of Object.values(z.files)) {
                   if(zobj.dir) continue;
                   if(zobj.name.startsWith('__')) continue;  // file compressed from user's local PC -> continue
                   // if(!file.name.includes(zobj.name.replace('.block', ''))) continue;  // file name not matching
                   
                   zobj.async("blob")
                   .then(zblob => {
                         zfile = new File([zblob], zobj.name, {type: "text/plain;charset=utf-8"});
                         reader.readAsText(zfile);
                   });
                }
             });
       } catch (err) {
             console.error(err);
       } // finally {
       //     reader.readAsText(file);
       // }

       function processAudio(composer) {
          const audio_list = composer.audio;
          if(!audio_list || !audio_list.length) {
                setItemComposer(composer);
                return composer;
          }
          
          const audio_DB = db.transaction(["audio"], "readwrite").objectStore("audio");
          audio_list.forEach(audio => {
                audio_DB.put({ name: audio.name, wav: new Uint8Array(audio.wav) });
                delete audio.wav;
          });
          composer.audio = audio_list;
          setItemComposer(composer);
          return composer;
       }
       async function processRoboids(composer) {
          let roboid_models = composer?.roboid_models;
          if(roboid_models && roboid_models.length > 0) {  // open file of new version
                if(composer.worldModel) delete composer.worldModel;
                for(let i=0; i<roboid_models.length; i++) {
                   const roboid = roboid_models[i];
                   if(i == 0) emptyWorld(roboid);
                   await importRoboid(roboid);
                }

                composer = getItemComposer();
                if(composer.roboid_models) delete composer.roboid_models;
                if(composer.camera) delete composer.camera;
                setItemComposer(composer);
                location.reload();
          }
          else {  // opening file of Beta Version or file with no roboid model (Impossible because block urn has changed)
             composer = getItemComposer();
             if(composer.roboid_models) delete composer.roboid_models;
             if(composer.camera) delete composer.camera;
             setItemComposer(composer);
             location.reload();
          }
       }
    }

    function mergeWorld(model, imported_roboids) {
       // find roboid and replace 
       model.items.forEach(d => {
          if(d.class === "roboid") {
             let imported = imported_roboids.find(r => d.uid === r.uid);
             d.items = deepCopy(imported.model).items;
             d.pid = imported.pid;
             d.script = imported.script;
          }
          if(d.class === "robot") {
             d.items.forEach(r => {
                let imported = imported_roboids.find(e => e.uid === r.uid);
                r.items = deepCopy(imported.model).items;
                r.pid = imported.pid;
                r.script = imported.script;
             });
          }
       });
       return model;

       function deepCopy(item) {
          return JSON.parse(JSON.stringify(item));
       }
    }

    function flattenWorld(world) {
       let {name, creator, uid} = world;
       world.urn = '_';
       const flat = [{"class":"world", name, creator, uid, "urn": '_'}];
       if(world.items) flattenItems(world, flat);
       return flat;
    }

    // recursive function 
    function flattenItems(obj, arr) {
       obj.items.forEach(item => {
          let parent = obj.urn;
          let separator = separators[item.class] || "";
          let urn = item.name + separator;
          if(parent != '_') urn = parent + urn; 
          
          item.urn = urn;
          item.parent = parent;
          const name = item.name;

          switch(item.class) {
             case "robot":
                arr.push({"class":"robot", name, parent, urn});
                break;
             case "roboid":
                const {uid, pid, script} = item;
                const meta = uid.split('-')[0];
                if(!item.index) {
                   let index = -1;
                   const siblings = obj.items.filter(r => r.uid == uid);
                   siblings.forEach(r => { index++; r.index = index; });
                }
                urn = urn.substring(0, urn.indexOf(separator)) + "*" + item.index + separator;
                item.urn = urn;
                item.parent = parent;
                arr.push({"class":"roboid", name, parent, meta, urn, uid, pid, script});
                break;
             case "slot":
                arr.push({...item, parent, urn, motor:true, notify:true});    
                // const module = item.module;
                // arr.push("class":"slot", name, parent, urn, module);
                break; 
             case "module":
                arr.push({...item, parent, urn});
                // arr.push({"class":"module", name, parent, urn});     
                break;   
             case "unit":
                // arr.push({"class":"unit", name, parent, urn});   
                arr.push({...item, parent, urn});
                break;     
             case "effector":
                arr.push({...item, leaf:true, motor:true, notify:true, items: undefined});
                break;
             case "sensor":
                arr.push({...item, leaf:true, sensory:true, notify:true, items: undefined});
                break;
             case "command":
                arr.push({...item, leaf:true, motor:true, notify:true, ack: true, items: undefined});
                break;
             case "event":
                arr.push({...item, leaf:true, sensory:true, notify:true, ack: true, items: undefined});
                break;
             case "servo":
                arr.push({...item, leaf:true, motor:true, notify:true, ack: true, reply:true, feedback: true, items: undefined});
                break;
             case "action":
                arr.push({...item, leaf:true, motor:true, notify:true, ack: true, reply:true, items: undefined});
                break;
             case "audio":
                arr.push({...item, leaf:true, motor:true, notify:true, items: undefined});  // ack: true, reply:true, feedback: true, 
                break;         
             case "constant":
                urn = parent + "^" + name;
                const value = item.value;
                arr.push({"class":"constant", name, parent, urn, value});
                break;
          }
          if (item.items) flattenItems(item, arr);
       });
       return;
    }

    function compile(roboid, organs, organoid) {
       let next = true;
       let script = roboid.script;
       const roboid_urn = roboid.urn;

       // remove find $ function and replace it to real device or constant
       while(next) {
          // extract urn
          const s = script.indexOf("$('");
          if(s === -1) next = false;
          else {
             const e = script.indexOf("')", s);
             if(s > e) {next = false; continue;}
             let urn = script.substring(s+3, e);

             // replace it to device
             let f = "$('" + urn + "')";
             urn = roboid_urn + urn;
             if(urn.includes("^")) { // constant?
                let cons = organs.find(d => d.urn === urn).value;
                if(cons.length > 1) {
                   if(!(cons.startsWith('[') && cons.endsWith(']'))) {
                      cons = `[${cons}]`;
                   }
                }
                script = script.replaceAll(f, cons);
             }
             else {
                const index = organoid.findIndex(d => d.urn === urn);
                script = script.replaceAll(f, `organoid[${index}]`);
             }
          }
       }
       return script; 
    }

