        delay(n) {
            return new Promise( r => setTimeout(r, n));
        }

        fire_event() {
            this.ev = true;
            this.wait_e = true;
        }
     
        async w(select) {   
            this.wait_e = false;
            if(select === undefined) {
                while(!this.wait_e) {
                    await this.delay(1);
                }
                return;
            }
            else {
                while(true) {
                    if(this.wait_e) {
                        if(this.s(select)) break;
                    }
                    await this.delay(1);
                }
            }
        }

