    function arrayEquals(a, b) {
        return Array.isArray(a) &&
            Array.isArray(b) &&
            a.length === b.length &&
            a.every((val, index) => val === b[index]);
    }

    class Spine {
        constructor(roboid) {
            this.dongle = roboid?.dongle;
            this.urn = roboid?.urn;
        }
        
        get() {
            if(!this.dongle) return [];
            let sensory = [];
            if(this.dongle.mode === 'Express') {  // NUS Protocol
                switch(this.dongle.client.pid) {
                    case 0x14:   // Beagle
                        sensory = this.dongle.NUS_buffer.splice(0, this.dongle.NUS_tail);
                        sensory = sensory.map(sen => sen.slice(3, -2));
                        break;
                    case 0x1A:  // AudioBot
                        sensory = this.dongle.sensory.slice(3, -2);
                        this.dongle.NUS_buffer.splice(0, this.dongle.NUS_tail);
                        break;
                }
                this.dongle.NUS_tail = 0;
            }
            else  // Roboid Protocol
                sensory = convertHex(this.dongle.sensory);
            return sensory;
        }

        put(packet) {
            if(!this.dongle) return;
            if(!packet) return;
            let motor = convertAscii(packet);
            motor = new Uint8Array(motor);
            if(this.dongle.mode == 'Express')  // NUS data
                motor = new Uint8Array(packet);
            this.dongle.motor = motor;
            this.dongle.SEND = true;
        }
    }

    function convertHex(line) {
        const sensory = [];
        // extract payload except address '-'
        const index = line.findIndex(d => d === 45);
        const payload = line.slice(0, index);
     
        // convert payload to byte array
        const numbers = payload.map(d => String.fromCharCode(d));
        for(let i=0; i<20; i++) {
           const hex = '0x' + numbers[2*i] + numbers[2*i+1];
           sensory.push(+hex);
        }
        return sensory;
    }

    function convertAscii(motor){
        const packet = [];
        if(!motor) return packet;

        motor.forEach(d => {
            packet.push(ascii((d >> 4) & 0x0f));
            packet.push(ascii(d & 0x0f));
        });
        packet.push(13);
        return packet;

        function ascii(nibble) {
            if(nibble > 9) return nibble + 55;
            else return nibble + 48;
        }
    }

