    class Keyboard {
        down_key = 0;
        up_key = 0;
        pressed_keys = [];
        KEYDOWN_FLAG = false;
        KEYUP_FLAG = false;

        constructor() {
            this.setListener();
        }

        setListener() {
            window.onkeydown = (e) => this.onKeyDown(e);
            window.onkeyup = (e) => this.onKeyUp(e);
        }
        onKeyDown(e) {
            const code = e.keyCode;
            this.down_key = code;
            this.pressed_keys[code] = true;
            this.KEYDOWN_FLAG = true;
        }
        onKeyUp(e) {
            const code = e.keyCode;
            this.up_key = code;
            this.pressed_keys[code] = false;
            this.KEYUP_FLAG = true;
        }

        keydown(key) {
            if(this.KEYDOWN_FLAG) {
                if(!key) return true;
                if(this.down_key === key) return true;
            }
            return false;
        }
        keyup(key) {
            if(this.KEYUP_FLAG) {
                if(!key) return true;
                if(this.up_key === key) return true;
            }
            return false;
        }
        keypressed(keys) {
            if(!keys.reduce((a, c) => a || c, false)) return false;
            for(let key of keys) {
                if(key) {
                    if(!this.pressed_keys[+key]) return false;
                }
            }
            return true;       
        }

        clear() {
            this.KEYDOWN_FLAG = false;
            this.KEYUP_FLAG = false;
        }
    }

