const __playSound = function(file, volume, repeat) {
    if(!file) return;
    const audio = new Audio();
    const pop = file.split("/");
    if(pop[0] === "record" || pop[0] === "local") { // if the clip is recordClip or localClip
        var filename = pop[0] + "/" + pop[1];
        fileReader.onload = async () => { // play the sound using fileReader
            var result = fileReader.result;
            var audioBuffer = await audioContext.decodeAudioData(result);
            audioBufferSourceNode = audioContext.createBufferSource();
            audioBufferSourceNode.buffer = audioBuffer;
            var gainNode = audioContext.createGain();
            gainNode.gain.value = volume / 100;
            audioBufferSourceNode.connect(gainNode).connect(audioContext.destination);
            audioBufferSourceNode.start(0, 0);
        };
        const audio_DB = db.transaction(["audio"], "readwrite").objectStore("audio");
        const request = audio_DB.get(filename);
        request.onsuccess = (event) => {
            let arrayBuffer = event.target.result.wav;	
            const blob = new Blob([arrayBuffer], { type: "audio/wav" });
            const audioFile = new File([blob], filename, { type: "audio/wav" });	
            fileReader.readAsArrayBuffer(audioFile);   
        }
    } else { // if the clip is soundClip
        audio.src = 'https://robomation.s3.ap-northeast-2.amazonaws.com/BlockComposer_Audio/' + file + '.wav';
        audio.id = 'sound_clip';
        audio.volume = volume / 100;
        audio.autoplay = true;
        audio.loop = repeat;
        audio.play();
        if(!document.querySelector('audio#sound_clip'))
            document.body.appendChild(audio);
    }
}
const __setTTSOption = function(lang, name) {
    const composer = getItemComposer();
    const TTS = composer.TTS;
    TTS.selected = { lang: lang, name: name };
    composer.TTS = TTS;
    setItemComposer(composer);
}
const __speak = function(text) {
    const voiceList = window.speechSynthesis.getVoices();
    const synthesis = new SpeechSynthesisUtterance();
    synthesis.text = text;
    
    const composer = getItemComposer();
    const selected = composer?.TTS?.selected;
    if(selected) {
        synthesis.lang = selected.lang;
        synthesis.voice = voiceList.find(v => v.name === selected.name && v.lang === selected.lang);
    }
    window.speechSynthesis.speak(synthesis);
}

const __speechRecognition = function(lang, running) {  // New Version
    __ASR.onresult = async(event) => {
        var result = event.results[0][0].transcript;
        __ASR_result.text = result;
        __ASR_result.lang = lang; // ko-KR en-US
        __ASR.stop();
        setTimeout(() => {
            __ASR_result.text = '';
            __ASR.start();
        }, 100);
    }
    if(running) __ASR.start();
    else __ASR.abort();
}
const __speechRecognitionResult = function() {
    return __ASR_result?.text || '';
}
const __exit = function() { 
    if(PLAYING) popup(); 
}
