const __getSpeed = function(urn, value) {
    const robot = urn.split('*')[0];
    const speed = { 
        "Hamster": CONST.HAMSTER.SPEED,
        "HamsterS": CONST.HAMSTER_S.SPEED, 
        "Pio": CONST.PIO.SPEED, 
        "Turtle": CONST.TURTLE.SPEED,
        "Beagle": CONST.BEAGLE.SPEED 
    };
    if(value === undefined) return speed[robot];
    else {
        const value_to_speed = {
            "Hamster": CONST.HAMSTER.VAL_TO_SPEED,
            "HamsterS": CONST.HAMSTER_S.VAL_TO_SPEED, 
            "Pio": CONST.PIO.VAL_TO_SPEED, 
            "Turtle": CONST.TURTLE.VAL_TO_SPEED,
            "Beagle": CONST.BEAGLE.VAL_TO_SPEED
        }

        if(typeof value === "string" && value.includes("Math")) value += (" * " + value_to_speed[robot]);
        else value *= value_to_speed[robot];
        
        return value;
    }
}
