const __pivot = async function(urn, unit, direction, degree, wait_w) {
    const roboid = roboids.find(r => r.urn == urn + ':');
    while(roboid.spine?.wait) { await __wait(1); }
    if($(urn + ":wheel.move").d != 0) {
        $(urn + ":wheel.move").d = 0;
    }
    const tmp = unit.split(' ');  // tmp[0]: left/right, tmp[1]: pen/wheel
    switch(urn.split('*')[0]) {
        case "HamsterS":
            switch(tmp[1]) {
                case "pen":
                    $(urn + ":wheel.speed.left").d = (tmp[0] == "left") 
                        ? ( (direction == "forward") ? __calc_inner_velocity(urn, __getSpeed(urn)) : __calc_inner_velocity(urn, __getSpeed(urn)) * -1 )
                        : ( (direction == "forward") ? __getSpeed(urn) : __getSpeed(urn) * -1 );
                    $(urn + ":wheel.speed.right").d = (tmp[0] == "left") 
                        ? ( (direction == "forward") ? __getSpeed(urn) : __getSpeed(urn) * -1 )
                        : ( (direction == "forward") ? __calc_inner_velocity(urn, __getSpeed(urn)) : __calc_inner_velocity(urn, __getSpeed(urn)) * -1 );
                    $(urn + ":wheel.move").d = __calc_circle_to_pulse(urn, degree, 0);  // CONST.HAMSTER_S.DEG_TO_PULSE_PIVOT_PEN
                    break;
                case "wheel":
                    $(urn + ":wheel.speed.left").d = (tmp[0] == "left") 
                        ? 0 
                        : ( (direction == "forward") ? __getSpeed(urn) : __getSpeed(urn) * -1 );
                    $(urn + ":wheel.speed.right").d = (tmp[0] == "left") 
                        ? ( (direction == "forward") ? __getSpeed(urn) : __getSpeed(urn) * -1 )
                        : 0;
                    $(urn + ":wheel.move").d = __calc_pivot_to_pulse(urn, degree);
                    break;
            }
            if(wait_w) await $(urn + ":wheel.!move").w();
            break;
        case "Turtle":
            $(urn + ":wheel.speed.left").d = (tmp[0] == "left") 
                ? 0 
                : ( (direction == "forward") ? __getSpeed(urn) : __getSpeed(urn) * -1 );
            $(urn + ":wheel.speed.right").d = (tmp[0] == "left") 
                ? ( (direction == "forward") ? __getSpeed(urn) : __getSpeed(urn) * -1 )
                : 0;
            $(urn + ":wheel.move").d = __calc_pivot_to_pulse(urn, degree, tmp[0]);
            if(wait_w) await $(urn + ":wheel.!move").w();
            break;
    }
}
const __pivot_circle = async function(urn, unit, direction, radius, degree, wait_w) {
    const roboid = roboids.find(r => r.urn == urn + ':');
    while(roboid.spine?.wait) { await __wait(1); }
    if($(urn + ":wheel.move").d != 0) {
        $(urn + ":wheel.move").d = 0;
    }
    const tmp = direction.split(' ');  // tmp[0]: left/right, tmp[1]: forward/backward
    let speed = (tmp[1] == "forward") ? __getSpeed(urn) : __getSpeed(urn) * -1;
    switch(urn.split('*')[0]) {
        case "HamsterS":
            radius = radius / CONST.HAMSTER_S.CM_TO_PULSE;
            const pen = unit.split(' ')[0];  // left/right
            if(pen == "left") {
                if(tmp[0] == "left") {  // left pen & left 
                    radius += CONST.HAMSTER_S.PEN_CENTER_DISTANCE;
                    $(urn + ":wheel.speed.left").d = __calc_inner_velocity(urn, speed, radius);
                    $(urn + ":wheel.speed.right").d = speed;
                    $(urn + ":wheel.move").d = __calc_circle_to_pulse(urn, degree, radius, true);  // CONST.HAMSTER_S.DEG_TO_PULSE_CIRCLE_PEN_SAME
                }
                else {  // left pen & right
                    if(radius >= CONST.HAMSTER_S.PEN_CENTER_DISTANCE) {
                        radius -= CONST.HAMSTER_S.PEN_CENTER_DISTANCE;
                        $(urn + ":wheel.speed.left").d = speed;
                        $(urn + ":wheel.speed.right").d = __calc_inner_velocity(urn, speed, radius);
                    }
                    else {
                        radius = (radius - CONST.HAMSTER_S.PEN_CENTER_DISTANCE) * -1;
                        $(urn + ":wheel.speed.left").d = __calc_inner_velocity(urn, speed, radius) * -1;
                        $(urn + ":wheel.speed.right").d = speed * -1;
                    }
                    $(urn + ":wheel.move").d = __calc_circle_to_pulse(urn, degree, radius, false);  // CONST.HAMSTER_S.DEG_TO_PULSE_CIRCLE_PEN_DIFF
                }
            }
            else if(pen == "right") {
                if(tmp[0] == "left") {  // right pen & left 
                    if(radius >= CONST.HAMSTER_S.PEN_CENTER_DISTANCE) {
                        radius -= CONST.HAMSTER_S.PEN_CENTER_DISTANCE;
                        $(urn + ":wheel.speed.left").d = __calc_inner_velocity(urn, speed, radius);
                        $(urn + ":wheel.speed.right").d = speed;
                    }
                    else {
                        radius = (radius - CONST.HAMSTER_S.PEN_CENTER_DISTANCE) * -1;
                        $(urn + ":wheel.speed.left").d = speed * -1;
                        $(urn + ":wheel.speed.right").d = __calc_inner_velocity(urn, speed, radius) * -1;
                    }
                    $(urn + ":wheel.move").d = __calc_circle_to_pulse(urn, degree, radius, false); 
                }
                else {  // right pen & right
                    radius += CONST.HAMSTER_S.PEN_CENTER_DISTANCE;
                    $(urn + ":wheel.speed.left").d = speed;
                    $(urn + ":wheel.speed.right").d = __calc_inner_velocity(urn, speed, radius);
                    $(urn + ":wheel.move").d = __calc_circle_to_pulse(urn, degree, radius, true);  // CONST.HAMSTER_S.DEG_TO_PULSE_CIRCLE_PEN_SAME
                }
            }
            if(wait_w) await $(urn + ":wheel.!move").w();
            break;
        case "Turtle":
            radius = radius / CONST.TURTLE.CM_TO_PULSE;
            $(urn + ":wheel.speed.left").d = (tmp[0] == "left") ? __calc_inner_velocity(urn, speed, radius) : speed;
            $(urn + ":wheel.speed.right").d = (tmp[0] == "left") ? speed : __calc_inner_velocity(urn, speed, radius);
            $(urn + ":wheel.move").d = __calc_circle_to_pulse(urn, degree, radius, tmp[0]);
            if(wait_w) await $(urn + ":wheel.!move").w();
            break;
    }
}

