const __evaluate_move_forward = async function(roboid) {
    let urn = roboid.urn, wait = roboid.spine.grid.wait;
    switch(urn.split('*')[0]) {
        case "Hamster":
            if(roboid.spine.grid.state == 1) {
                if(roboid.spine.grid.counter < 2) {
                    if($(urn + 'floor.left').d < 50 && $(urn + 'floor.right').d < 50) roboid.spine.grid.counter++;
                    else roboid.spine.grid.counter = 0;

                    let diff = ($(urn + 'floor.left').d - $(urn + 'floor.right').d) * 0.25;
                    $(urn + 'wheel.speed.left').d = 45 + diff;
                    $(urn + 'wheel.speed.right').d = 45 - diff;
                }
                else {
                    roboid.spine.grid.state = 2;
                    roboid.spine.grid.counter = 0;
                }
            }
            else if(roboid.spine.grid.state == 2) {
                if(roboid.spine.grid.counter < 10) {
                    roboid.spine.grid.counter++;

                    let diff = ($(urn + 'floor.left').d - $(urn + 'floor.right').d) * 0.25;
                    $(urn + 'wheel.speed.left').d = 45 + diff;
                    $(urn + 'wheel.speed.right').d = 45 - diff;
                }
                else {
                    $(urn + 'wheel.speed.left').d = 0;
                    $(urn + 'wheel.speed.right').d = 0;

                    if(roboid.spine.wait) roboid.spine.wait = false;
                }
            }
            break;
        case "HamsterS":
            if($(urn + 'wheel.move').d != 0) {
                $(urn + 'wheel.move').d = 0;
            }
            if (($(urn + 'floor.left').d) < 20 && ($(urn + 'floor.right').d) < 20) {
                roboid.spine.grid = { key: 0, state: 2 };
                $(urn + 'wheel.speed.left').d = 45;
                $(urn + 'wheel.speed.right').d = 45;
                $(urn + 'wheel.move').d = __getDistance(urn, 1.3, "cm");
                if(wait) await $(urn + 'wheel.!move').w();

                if(roboid.spine.wait) roboid.spine.wait = false;
            } else {
                if (($(urn + 'floor.left').d) < 50 && ($(urn + 'floor.right').d) < 50) {
                    $(urn + 'wheel.speed.left').d = 45;
                    $(urn + 'wheel.speed.right').d = 45;
                } else {
                    let diff = (($(urn + 'floor.left').d) - ($(urn + 'floor.right').d)) * 0.25;
                    $(urn + 'wheel.speed.left').d = 45 + diff;
                    $(urn + 'wheel.speed.right').d = 45 - diff;
                }
            }
            break;
    }
}
const __evaluate_turn = async function(roboid, dir) {  // dir : left/right
    let urn = roboid.urn;
    let { wait, state } = roboid.spine.grid;
    let main = (dir == "left") ? $(urn + 'floor.left').d : $(urn + 'floor.right').d;
    let sub = (dir == "left") ? $(urn + 'floor.right').d : $(urn + 'floor.left').d;

    if(state == 1) {
        if(roboid.spine.grid.counter < 2) {
            if(main > 50)
                roboid.spine.grid.counter++;        
        }
        else {
            roboid.spine.grid.counter = 0;
            roboid.spine.grid.state = 2;    
        }
    }
    else if(state == 2) {
        if(main < 20) roboid.spine.grid.state = 3;
    }
    else if(state == 3) {
        if(roboid.spine.grid.counter < 2) {
            if(main < 20)
                roboid.spine.grid.counter++;        
        }
        else {
            roboid.spine.grid.counter = 0;
            roboid.spine.grid.state = 4;    
        }
    }
    else if(state == 4) {
        if(main > 50) roboid.spine.grid.state = 5;
    }
    else if(state == 5){
        let diff = (main - sub) * 0.5;
        if(diff > -15) {
            $(urn + 'wheel.speed.left').d = 0;
            $(urn + 'wheel.speed.right').d = 0;
            roboid.spine.grid = { key: 0, state: 6, counter: 0 };

            if(roboid.spine.wait) roboid.spine.wait = false;
        }
        else {
            $(urn + 'wheel.speed.left').d = diff;
            $(urn + 'wheel.speed.right').d = -diff;
        }
    }
}
const __evaluate_move_state = async function(roboid, arr) {  // arr: [left_1, right_1, dist_1, left_2, right_2, dist_2] 
    let urn = roboid.urn, wait = roboid.spine.grid.wait;
    switch(urn.split('*')[0]) {
        case "Pio":
            if(roboid.spine.grid.counter > 20) {  // step 1
                if(roboid.spine.grid.state == 1) {
                    if (!($(urn + 'wheel.moving').d)) {
                        roboid.spine.grid.state = 2;
                        roboid.spine.grid.counter = 0;
                        if($(urn + 'wheel.move').d != 0) {
                            $(urn + 'wheel.move').d = 0;
                        }
                        $(urn + 'wheel.speed.left').d = arr[0];
                        $(urn + 'wheel.speed.right').d = arr[1];
                        $(urn + 'wheel.move').d = __getDistance(urn, arr[2], "cm");
                        if(wait)  await $(urn + 'wheel.!move').w();
                    }
                    else {
                        roboid.spine.grid.counter = 0;
                    }
                }
            }
            if(roboid.spine.grid.counter > 20) {  // step 2
                if (roboid.spine.grid.state == 2 && !($(urn + 'wheel.moving').d)) { 
                    roboid.spine.grid.state = 3;
                    roboid.spine.grid.counter = 0;
                    if($(urn + 'wheel.move').d != 0) {
                        $(urn + 'wheel.move').d = 0;
                    }
                    $(urn + 'wheel.speed.left').d = arr[3];
                    $(urn + 'wheel.speed.right').d = arr[4];
                    $(urn + 'wheel.move').d = __getDistance(urn, arr[5], "cm");
                    if(wait) await $(urn + 'wheel.!move').w();
            
                    if(roboid.spine.wait) roboid.spine.wait = false;
                }
            }
            break;
    }
}
`;

    const gridCode = `
roboids.forEach(r => {
    if(!r.spine?.grid) return;

    // key: [ 1: move_forward, 2: move_backward, 3: move_left, 4: move_right, 5: turn_left, 6: turn_right ]
    const { key, state, counter } = r.spine.grid;     
    switch(r.urn.split('*')[0]) {
        case "Hamster":
            if(key == 1) {  
                if(state == 0) __move_forward(r);
                else __evaluate_move_forward(r);
            }
            if(key == 5) {
                if(state == 0) __turn_left(r);
                __evaluate_turn(r, "left");
            }
            if(key == 6) {
                if(state == 0) __turn_right(r);
                __evaluate_turn(r, "right");
            }
            break;
        case "HamsterS":
            if(key == 1) {  
                if(state == 0) __move_forward(r);
                if(state == 1) __evaluate_move_forward(r);
            }
            if(key == 5 && state == 0) __turn_left(r);
            if(key == 6 && state == 0) __turn_right(r);
            break;
        case "Pio":
            if(key == 1 && state == 0) __move_forward(r);
            if(key == 2 && state == 0) __move_backward(r);
            if(key == 3) {
                if(state == 0) __move_left(r);
                __evaluate_move_state(r, [-100, 100, 3.8, 100, 100, 11.45]);  
                r.spine.grid.counter++;
            }
            if(key == 4) {
                if(state == 0) __move_right(r);
                __evaluate_move_state(r, [100, -100, 3.8, 100, 100, 11.45]);  
                r.spine.grid.counter++;
            }
            if(key == 5) {
                if(state == 0) __turn_left(r);
                __evaluate_move_state(r, [-100, 100, 3.8, 100, 100, 1.45]);  
                r.spine.grid.counter++;
            }
            if(key == 6) {
                if(state == 0) __turn_right(r);
                __evaluate_move_state(r, [100, -100, 3.8, 100, 100, 1.45]); 
                r.spine.grid.counter++;
            }
            break;
    }
});
