    const SERIALIZE_LENGTH = {
      "CONTROL": 24,
      "AUDIO": 104,
      "MIXED": 126,
    };
    const DESERIALIZE_LENGTH = {
      "CONTROL": 30,
      // "AUDIO": 104,
      // "MIXED": 126,
    };

    let opusRecorder;
    let control_data_payload;
    function deserializeAudio(spine, organs, organoid) {
        const packet = spine.get();
        spine.audio = spine.audio || {};

        switch(packet[0]) {  // Message ID
          case 0x10:  // Control Data
            if(packet[1] !== DESERIALIZE_LENGTH.CONTROL - 2 || packet[2] !== 0xD0)  // check validity
              return;
            
            control_data_payload = new Array(SERIALIZE_LENGTH.CONTROL - 2).fill(0);
            for(let i=0; i<control_data_payload.length; i++) {  // copy control data payload (packet[2] ~ packet[23])
              control_data_payload[i] = packet[2+i];
            }
      
            spine.audio.send = spine.audio.send || {};
            spine.audio.send.complete = (packet[22] >> 6) & 0x03;
            spine.audio.send.ack = (packet[22] & 0x3F);
      
            spine.audio.play = spine.audio.play || {};
            const play = (packet[23] >> 6) & 0x03;
            if(spine.audio.play.complete === undefined) 
                spine.audio.play.init = play;
            spine.audio.play.complete = (play - spine.audio.play.init < 0) ? (play + 4 - spine.audio.play.init) % 4 : (play - spine.audio.play.init) % 4;
            spine.audio.play.ack = packet[23] & 0x3F;
      
            spine.ev.audio = spine.ev.audio || [];
            const audio_output = organs.filter(d => d.class == 'audio' && d.type == 'out');
            audio_output.forEach(audio => {
              let idx = spine.ev.audio.findIndex(d => d?.type == audio.source);
              if(idx !== -1) {
                if(spine.audio.origin) {
                  let pos = spine.audio.origin.findIndex(d => d?.source == audio.source);
                  if(pos !== -1 && spine.audio.origin[pos]?.end === spine.audio.send.index) {
                    spine.ev.audio[idx].end++;
                    spine.audio.origin.shift();
                    if(spine.audio.origin.length > 0) 
                      spine.audio.source = spine.audio.origin[0].source;
                  }
                }
                const audio_event = organs.find(d => d.class == 'event' && d.name == '!' + audio.name);
                const event = organoid.find(d => d.target.name == audio_event.name);
                if(!spine.audio.send.error) 
                  event.e = spine.ev.audio[idx].end;
                spine.audio.send.error = false;
              }
            });
            // const audio_feedback = organs.find(d => d.class == 'sensor' && d.name == '~' + audio_output.name);
            // const sensor = organoid.find(d => d.target.name == audio_feedback.name);
            // sensor.d = spine.audio.play.ack;
            break;
        }
    }
      
    function serializeAudio(spine, organs, organoid) {
        if(!spine.audio.send || !spine.audio.play) return;

        const audio_output = organs.filter(d => d.class == 'audio' && d.type == 'out');
        if(!audio_output.length) return;

        if(spine.audio.send.count === undefined && spine.audio.play.complete === 0) {
          spine.audio.send.count = 0;
          spine.audio.send.index = 0;
        }
        audio_output.forEach(audio => {
          const source = audio.source;  /* built-in | local | tts | cloud | stream */
          const value = audio.value[0];
      
          let idx = spine.ev.audio.findIndex(d => d?.type == source);
          if(idx == -1) {
            spine.ev.audio.push({ type: source, start: 0, end: 0 });
            idx = spine.ev.audio.length - 1;
          }

          const item = organoid.find(d => d.target.name == audio.name);
          if(item.command_id === spine.ev.audio[idx].start + 1) {
            spine.ev.audio[idx].start++;
            spine.audio.source = source;
            spine.audio.origin = spine.audio.origin || [];  // list of origin wav data
            switch(source) {
              case 'built-in':
                // put integer into the packet directly to sound the built-in audio.
                break;
              case 'local':
                processLocalFile(spine, value);
                break;
              case 'tts':
                processTTS(spine, value);
                break;
            }
          }
        });
        sendAudioPacket(spine);
        return;
    }
      
    async function processLocalFile(spine, filename) {
        if(!filename) {  // undefined or 0
          // get unmixed audio
          let idx = spine.audio.origin.findIndex(d => d.source == spine.audio.source);
          let origin = spine.audio.origin[idx];
          spine.audio.origin.splice(idx, 1);  // get recent local origin data and remove from origin list

          opusRecorder = new OpusRecorder();
          opusRecorder.unmixAudio(spine.audio.wav, origin.wav, origin.start)
          .then(async blob => {
            if(!blob) {      
              spine.audio.wav = null;
              spine.audio.buffer = null;
              return;
            }

            window.addEventListener('opusEncode', (e) => {  
              spine.audio.wav = e.detail.wav;
              spine.audio.buffer = e.detail.opus;
            }, { once: true });
      
            let audioBuffer = await blob.arrayBuffer();
            await opusRecorder.processAudioData('audio_player', audioBuffer);
            opusRecorder.terminateWorker();
          });
          return;
        }
        if(!isAudioFile(filename)) return;

        const audioData = spine.audio_list.get(filename);  // if audio file is not valid, return
        if(!audioData) return;

        spine.audio.origin.unshift({
          source: spine.audio.source, name: filename, wav: audioData
        });

        // get opus data for origin wav file
        if(spine.audio.buffer) {
          let get_origin = false;
          opusRecorder = new OpusRecorder();
          window.addEventListener('opusEncode', (e) => {  
              let pos = spine.audio.origin.findIndex(d => d.source == spine.audio.source && d.name === filename);
              if(pos !== -1) {
                spine.audio.origin[pos].opus = e.detail.opus;
              }
              opusRecorder.terminateWorker();
              get_origin = true;
            }, { once: true });
          let blob = new Blob([audioData], { type: 'audio/wav' });
          let audioBuffer = await blob.arrayBuffer();
          opusRecorder.processAudioData('audio_origin', audioBuffer);

          const delay = n => new Promise(r => setTimeout(r, n));
          while(!get_origin) await delay(1);
        }

        // get mixed audio
        const start_index = spine.audio.send.index;
        opusRecorder = new OpusRecorder();
        opusRecorder.mixAudio(spine.audio.wav, audioData, start_index)
        .then(async blob => {
          window.addEventListener('opusEncode', (e) => {  
            spine.audio.wav = e.detail.wav;
            spine.audio.buffer = e.detail.opus;

            let pos = spine.audio.origin.findIndex(d => d.source == spine.audio.source && d.name === filename);
            if(pos !== -1) {
              spine.audio.origin[pos].start = start_index;
              spine.audio.origin[pos].end = start_index + (spine.audio.origin[pos].opus ? spine.audio.origin[pos].opus.length : spine.audio.buffer.length);    
            }

            // spine.audio.send.count = 0;
          }, { once: true });

          let audioBuffer = await blob.arrayBuffer();
          await opusRecorder.processAudioData('audio_player', audioBuffer); 
        });
        
        return;

        function isAudioFile(value) {
          const audioExtensions = ['wav', 'mp3', 'mp4', 'ogg', 'opus', 'flac'];
          const match = value.match(/\.([a-zA-Z0-9]+)$/);
          if (!match) return false;
          const ext = match[1].toLowerCase();
          return audioExtensions.includes(ext);
      }
    }
      
    async function processTTS(spine, text) {
        // if(!TTSConverter || !TTSConverter.isConfigLoaded()) return;
        if(!text) {  // undefined or 0 
          // get unmixed audio
          let idx = spine.audio.origin.findIndex(d => d.source == spine.audio.source);
          let origin = spine.audio.origin[idx];
          spine.audio.origin.splice(idx, 1);  // get recent local origin data and remove from origin list

          opusRecorder = new OpusRecorder();
          opusRecorder.unmixAudio(spine.audio.wav, origin.wav, origin.start)
          .then(async blob => {
            if(!blob) {      
              spine.audio.wav = null;
              spine.audio.buffer = null;
              return;
            }
            window.addEventListener('opusEncode', (e) => {  
              spine.audio.wav = e.detail.wav;
              spine.audio.buffer = e.detail.opus;
            }, { once: true });
      
            let audioBuffer = await blob.arrayBuffer();
            await opusRecorder.processAudioData('audio_player', audioBuffer); 
            opusRecorder.terminateWorker();
          });
          return;
        }
        
        // let textToSpeech = TTSConverter.speak(text, { rawdata: 'array', variant: 'f1' });
        // textToSpeech = new Uint8Array(textToSpeech);

        // fetch TTS data from text
        const input = { 
          "text": text, 
          "lang": (getItemComposer().options?.lang == 'ko') ? "ko-KR" : "en-US",  // en-US  
          "gender": "FEMALE"
        };
        fetch('https://pv5cstxx69.execute-api.ap-northeast-2.amazonaws.com/api/tts', {  // API Gateway for Google-Cloud-Text-to-Speech
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(input)
        })
        .then(res => res.arrayBuffer())
        .then(buffer => {
          const wav = new Uint8Array(buffer);        // convert base64 text to pcm data
          const textToSpeech = new Blob([wav], { type: 'audio/wav' });
          const fileReader = new FileReader();
          fileReader.onload = async () => {                       // convert wav file to opus data
            let audioData = fileReader.result;
            audioData = new Uint8Array(audioData);
            
            spine.audio.origin.unshift({
              source: spine.audio.source, name: text, wav: audioData
            });

            // get opus data for origin wav file
            if(spine.audio.buffer) {
              let get_origin = false;
              opusRecorder = new OpusRecorder();
              window.addEventListener('opusEncode', (e) => {  
                let pos = spine.audio.origin.findIndex(d => d.source == spine.audio.source && d.name === text);
                if(pos !== -1) {
                  spine.audio.origin[pos].opus = e.detail.opus;
                }
                get_origin = true;
                opusRecorder.terminateWorker();
              }, { once: true });
              let blob = new Blob([audioData], { type: 'audio/wav' });
              let audioBuffer = await blob.arrayBuffer();
              opusRecorder.processAudioData('audio_origin', audioBuffer);

              const delay = n => new Promise(r => setTimeout(r, n));
              while(!get_origin) await delay(1);
            }

            // get mixed audio
            const start_index = spine.audio.send.index;
            opusRecorder = new OpusRecorder();
            opusRecorder.mixAudio(spine.audio.wav, audioData, start_index)
            .then(async blob => {
                window.addEventListener('opusEncode', (e) => { 
                  spine.audio.wav = e.detail.wav;
                  spine.audio.buffer = e.detail.opus;
                  
                  let pos = spine.audio.origin.findIndex(d => d.source == spine.audio.source && d.name === text);
                  if(pos !== -1) {
                    spine.audio.origin[pos].start = start_index;
                    spine.audio.origin[pos].end = start_index + (spine.audio.origin[pos].opus ? spine.audio.origin[pos].opus.length : spine.audio.buffer.length);    
                  }

                  // spine.audio.send.count = 0;
                }, { once: true }); 

                let audioBuffer = await blob.arrayBuffer();
                await opusRecorder.processAudioData('audio_player', audioBuffer);
            });
          };
          fileReader.readAsArrayBuffer(textToSpeech);

          // convert TTS data to wav file
          // opusRecorder.convertToWav(new Blob([textToSpeech], { type: 'audio/wav' }))
          // .then(async wav => {});
        });
        return;
    }

    function sendAudioPacket(spine) {
      const audioBuffer = spine.audio.buffer;
      if(!audioBuffer) {
        spine.audio.send.index = 0; // sendAudioPacket(spine, 0);
        return;
      }
      
      // ver 1: Audio Protocol
      // const packet_len = SERIALIZE_LENGTH.AUDIO;
      // const control_len = 0;
      // const message_id = 0x20;

      // ver 2: Mixed Protocol
      const packet_len = SERIALIZE_LENGTH.MIXED;
      const control_len = control_data_payload.length;
      const message_id = 0x30;
      
      let packet = new Array(packet_len + 5).fill(0);  // SERIALIZE_LENGTH.AUDIO + 5;  
      packet[0] = 0x5A; packet[1] = 0x49;  // Header
      packet[2] = packet_len;  // SERIALIZE_LENGTH.AUDIO (NUS Data Length)
      packet[3] = message_id;  // Message ID
      packet[4] = packet_len - 2;  // SERIALIZE_LENGTH.AUDIO - 2 (Data Length)

      // Control Data Payload
      for(let i=0; i<control_len; i++) {
        packet[5+i] = control_data_payload[i];
      }

      packet[5+control_len] = 0xA0;  // Audio Valid
      packet[6+control_len] = ((spine.audio.play?.complete || 0) << 6) + ((spine.audio.send?.ack || 0) & 0x3F);

      if(spine.audio.send.index >= audioBuffer.length) {
        let idx = spine.ev.audio.findIndex(d => d?.type == spine.audio?.source);
        if(spine.audio.play.complete === (spine.ev.audio[idx].end + 1) % 4) {
          spine.ev.audio[idx].end++;
        }
        spine.audio.wav = null;
        spine.audio.buffer = null;

        packet[5+control_len] = 0xE0;
        fillChecksum(packet, packet_len + 3);  // SERIALIZE_LENGTH.AUDIO + 3
        spine.put(packet);
        // sendAudioPacket(spine, index);
        return;
      }

      if(!canSend(spine)) { // if diff between send and play bigger than 8, do not send audio data
        let idx = spine.ev.audio.findIndex(d => d?.type == spine.audio?.source);
        if(spine.audio.play.complete === (spine.ev.audio[idx].end + 1) % 4) {
          spine.ev.audio[idx].end++;
          spine.audio.send.error = true;
        }

        spine.audio.cantsend = spine.audio.cantsend || 0;
        spine.audio.cantsend++;
        if(spine.audio.cantsend > 8) {
          spine.audio.send.count = 0;
          spine.audio.cantsend = 0;
        }

        fillChecksum(packet, packet_len + 3);  // SERIALIZE_LENGTH.AUDIO + 3
        spine.put(packet);
        // sendAudioPacket(spine, index);
        return;
      }
      spine.audio.cantsend = 0;
      
      let new_audio = spine.audio.play.complete % 4;      
      packet[5+control_len] = 0xAA;
      packet[6+control_len] = (new_audio << 6) + ((++spine.audio.send.count) & 0x3F);
      for(let i=0; i<100; i++) {
          packet[7+control_len+i] = audioBuffer[spine.audio.send.index++];
      }
      fillChecksum(packet, packet_len + 3);  // SERIALIZE_LENGTH.AUDIO + 3
      spine.put(packet);
      // sendAudioPacket(spine, index + 100); 
      return;
    }
      
    function canSend(spine) {
        spine.audio.send.count = spine.audio.send.count || 0;
        
        let send = spine.audio.send.count % 64;  // current send request count
        let play = spine.audio.play.ack;  // play ack from robot
        let sum = 0, diff = send - play;
        
        if(diff < 0) sum = 64;
        // if(diff >= -16 && diff < 0) sum = 16;
        // else if(diff >= -32 && diff < -16) sum = 32;
        // else if(diff >= -48 && diff < -32) sum = 48;
        // else if(diff >= -64 && diff < -48) sum = 64;
      
        spine.audio.cansend = spine.audio.cansend || true;
        if(send + sum - play >= 8) spine.audio.cansend = false;
        if(!spine.audio.cansend && send + sum - play < 4) spine.audio.cansend = true;
        
        console.log("send:", send, ", play:", play, ", how:", spine.audio.cansend, ", index:", spine.audio.send.index);
        
        return spine.audio.cansend;
    }
      
    function fillChecksum(packet, len) {
        if(!packet) return;
      
        let checkA = 0, checkB = 0;
        for(let i=0; i<len; i++) {
            checkA += packet[i];
            checkB += checkA;
        }
        packet[len] = checkA & 0xFF;
        packet[len+1] = checkB & 0xFF;
      
        return packet;
    }

