            for(let i=1; i<=2; i++) createLine(graph, [0, parseInt(graph.attr("height")) / 2 * i, parseInt(graph.attr("width")), parseInt(graph.attr("height")) / 2 * i]);  // horizontal line
            for(let i=0; i<=5; i++) createLine(graph, [parseInt(graph.attr("width")) / 6 * i, 0, parseInt(graph.attr("width")) / 6 * i, parseInt(graph.attr("height"))]);  // vertical line
