            /* turbo button */
            const turbo = wheel_frame.append('g').attr("id", "cmd_turbo");
            turbo.append('rect')
                .attr("width", 106) 
                .attr("height", 36)
                .attr("rx", 8)
                .attr("ry", 8)
                .attr("x", (234 - 106) / 2)
                .attr("y", 280)
                .style("fill", getColor("white"))
                .style("stroke", getColor("marine"))
                .style("stroke-width", "1px");
            turbo.append('image')
                .attr("xlink:href", 'icons/dashboard/turbo.svg')
                .attr("x", parseInt(turbo.select('rect').attr("x")) + 16)
                .attr("y", parseInt(turbo.select('rect').attr("y")) + 10)
                .attr("width", 16)
                .attr("height", 16);
            turbo.append('text')
                .attr("x", parseInt(turbo.select('rect').attr("x")) + 16 + 48)
                .attr("y", parseInt(turbo.select('rect').attr("y")) + 10 + 13)
