        function drawLidarFrame(frame) {
            const lidar_layout = frame.append('g')
                .attr("id", "lidar_layout")
                .attr("width", 400)
                .attr("height", 400)
                .attr("transform", "translate(40, 40)");
            for(let i=0; i<3; i++) createLine(lidar_layout, [0, 200*i, 400, 200*i]);
            for(let i=0; i<3; i++) createLine(lidar_layout, [200*i, 0, 200*i, 400]);
            createLine(lidar_layout, [100, 0, 300, 400]);
            createLine(lidar_layout, [300, 0, 100, 400]);
            createLine(lidar_layout, [0, 100, 400, 300]);
            createLine(lidar_layout, [0, 300, 400, 100]);
            lidar_layout.append('circle')
                .attr("cx", 200)
                .attr("cy", 200)
                .attr("r", 200)
                .attr("fill", "none")
                .attr("stroke", getColor("lightgray"))
                .attr("stroke-width", 1);
            const beagle_lidar = lidar_layout.append('g');
            beagle_lidar.append('image')  // svg
                .attr("width", 70)
                .attr("height", 70)
                .attr("x", (parseInt(lidar_layout.attr("width")) - 70) / 2)
                .attr("y", (parseInt(lidar_layout.attr("height")) - 70) / 2)
                .attr("xlink:href", spine.images.get('beagle.png'));
            for(let i=-2; i<=2; i++) {
                lidar_layout.append('text')
                    .attr("x", 200+(100-4)*i)
                    .attr("y", -8)
                    .style("font-size", "12px")
                    .style("font-weight", 400)
                    .style("fill", getColor("lightgray"))
                    .style("text-anchor", "middle")
                    .style("alignment-baseline", "middle")
                    .text(200 * i);
                lidar_layout.append('text')
                    .attr("x", 200+(100-4)*i)
                    .attr("y", 400+10)
                    .style("font-size", "12px")
                    .style("font-weight", 400)
                    .style("fill", getColor("lightgray"))
                    .style("text-anchor", "middle")
                    .style("alignment-baseline", "middle")
                    .text(200 * i);
                lidar_layout.append('text')
                    .attr("x", -4)
                    .attr("y", 200+(100-4)*i)
                    .style("font-size", "12px")
                    .style("font-weight", 400)
                    .style("fill", getColor("lightgray"))
                    .style("text-anchor", "end")
                    .style("alignment-baseline", "middle")
                    .text(200 * i);
                lidar_layout.append('text')
                    .attr("x", 400+4)
                    .attr("y", 200+(100-4)*i)
                    .style("font-size", "12px")
                    .style("font-weight", 400)
                    .style("fill", getColor("lightgray"))
                    .style("text-anchor", "start")
                    .style("alignment-baseline", "middle")
                    .text(200 * i);
            }
            for(let i=0; i<4; i++) {
                let x, y, rotate, trans_x, trans_y;
                if(i % 2 === 0) { x = 200; y = 200 + 230 * (i-1); rotate = 0; trans_x = 0; trans_y = 0; }
                else { x = 200 + 230 * ((i-2) % 2); y = 200; rotate = 90 * (i-2); trans_x = x; trans_y = y; }
                
                lidar_layout.append('text')
                    .attr("x", x)
                    .attr("y", y)
                    .attr("transform", `rotate(${rotate}, ${trans_x}, ${trans_y})`)
                    .style("font-size", "12px")
                    .style("font-weight", 400)
                    .style("fill", getColor("lightgray"))
                    .style("text-anchor", "middle")
                    .style("alignment-baseline", "middle")
                    .text((90 * i) + "°");
            }
        }

