        d3Exports.select('#cmd_lidar_connect').on('click', function() {
            $('lidar+connect').d = $('lidar+connect').d ^ 1;
            if($('lidar+connect').d) {
                d3Exports.select('#cmd_lidar_connect').select('rect').style("fill", getColor("gray"));
                d3Exports.select('#cmd_lidar_connect').select('image').attr("xlink:href", "icons/dashboard/lidar_disconnected.svg");
                d3Exports.select('#cmd_lidar_connect').select('text').text(instance$j.t('dashboard.Beagle.lidar.disconnect'));
            } else {
                d3Exports.select('#cmd_lidar_connect').select('rect').style("fill", getColor("marine"));
                d3Exports.select('#cmd_lidar_connect').select('image').attr("xlink:href", "icons/dashboard/lidar_connected.svg");
                d3Exports.select('#cmd_lidar_connect').select('text').text(instance$j.t('dashboard.Beagle.lidar.connect'));
                
                d3Exports.select('#lidar_layout').selectAll('circle').remove();
            }
        });

        if($('lidar+connect').d) {
            spine.dashboard.curTime = performance.now();
            if(spine.dashboard.curTime - spine.dashboard.oldTime > 20) {
                spine.dashboard.oldTime = spine.dashboard.curTime;
                const lidar_layout = d3Exports.select('#lidar_layout');
                lidar_layout.selectAll('circle').remove();
                for(let i=0; i<$('lidar+array').d.length; i++) {
                    let pos_data = transform2xy($('lidar+array').d[i], i);
                    if(pos_data) {
                        lidar_layout.append('circle')
                            .attr("cx", pos_data.x)
                            .attr("cy", pos_data.y)
                            .attr("r", "3px")
                            .style("fill", getColor("red"));
                    }
                }
            }
            function transform2xy(data, idx) {
                if(data & 0xFF00 == 0xFF00 || data < 50)  // invalid data
                    return null;
                let x = 200 + data * Math.sin(toRAD(idx - 180)); 
                let y = 200 + data * Math.cos(toRAD(idx - 180)); 
                if(x < 0 || x > 400 || y < 0 || y > 400)  // out of range
                    return null;
                return { x: x, y: y, dist: data };
                
                function toRAD(deg) { return deg * Math.PI / 180 }
            }
        }

        if(d3Exports.select('#encoder_left').node()) d3Exports.select('#encoder_left').text($('encoder.left').d);
