                d3Exports.select('#monitor_magnetometer_y').text($('magnetometer.y').d);
                if(!scopes.find(d => d.name === "magnetometer y")) {
                    scopes.push({ name: "magnetometer y", min: $('magnetometer.y').target.min, max: $('magnetometer.y').target.max, signals: [] });
                }
                const scope = scopes.find(d => d.name === "magnetometer y");
