        function keydown_event(e) {
            let key;
            
            if(e.code.includes('Shift')) {
                key = d3Exports.select('#Shift');
                d3Exports.select('#keyboard_joint').property("value", 3);
                d3Exports.select('#keyboard_joint').node().dispatchEvent(new Event('change', { bubbles: true }));
            } 
            else if(e.code.includes('Alt')) {
                key = d3Exports.select('#Alt');
                d3Exports.select('#keyboard_joint').property("value", 4);
                d3Exports.select('#keyboard_joint').node().dispatchEvent(new Event('change', { bubbles: true }));
            }
            else if(e.code.includes('Arrow')) {
                key = d3Exports.select('#' + e.code);
                switch(e.code) {
                    case "ArrowUp":
                        d3Exports.select('#keyboard_key').property("value", "up");
                        d3Exports.select('#keyboard_key').node().dispatchEvent(new Event('change', { bubbles: true }));
                        break;
                    case "ArrowDown":
                        d3Exports.select('#keyboard_key').property("value", "down");
                        d3Exports.select('#keyboard_key').node().dispatchEvent(new Event('change', { bubbles: true }));
                        break;
                    case "ArrowLeft":
                        d3Exports.select('#keyboard_key').property("value", "left");
                        d3Exports.select('#keyboard_key').node().dispatchEvent(new Event('change', { bubbles: true }));
                        break;
                    case "ArrowRight":
                        d3Exports.select('#keyboard_key').property("value", "right");
                        d3Exports.select('#keyboard_key').node().dispatchEvent(new Event('change', { bubbles: true }));
                        break;
                }
            }
            else if(e.code.includes('Space')) {
                key = d3Exports.select('#' + e.code);
            }
            
            if(key) {
                key.select('rect').style("fill", getColor("yellow"));
                key.select('text').style("fill", "black");
            }
        }
        function keyup_event(e) {
            let key;
            
            if(e.code.includes('Shift')) {
                key = d3Exports.select('#Shift');
                d3Exports.select('#keyboard_joint').property("value", 2);
                d3Exports.select('#keyboard_joint').node().dispatchEvent(new Event('change', { bubbles: true }));
            }
            else if(e.code.includes('Alt')) {
                key = d3Exports.select('#Alt');
                d3Exports.select('#keyboard_joint').property("value", 2);
                d3Exports.select('#keyboard_joint').node().dispatchEvent(new Event('change', { bubbles: true }));
            }
            else if(e.code.includes('Arrow')) {
                key = d3Exports.select('#' + e.code);
                d3Exports.select('#keyboard_key').property("value", "none");
                d3Exports.select('#keyboard_key').node().dispatchEvent(new Event('change', { bubbles: true }));
            }
            else if(e.code.includes('Space')) {
                key = d3Exports.select('#' + e.code);
                d3Exports.select('#keyboard_gripper').property("value", parseInt(d3Exports.select('#keyboard_gripper').property("value")) ^ 0x01);
                d3Exports.select('#keyboard_gripper').node().dispatchEvent(new Event('change', { bubbles: true }));
            }
            
            if(key) {
                key.select('rect').style("fill", getColor("lightgray"));
                key.select('text').style("fill", "gray");
            }
        }
        function add_key_event() {
            window.addEventListener("keydown", keydown_event);
            window.addEventListener("keyup", keyup_event);
        }
        function remove_key_event() {
            window.removeEventListener("keydown", keydown_event);
            window.removeEventListener("keyup", keyup_event);
        }

