            // const width_per_draw = 1;  
        
            spine.dashboard.scopes.forEach((scope, i) => {
                const {min, max, signals} = scope;
                const max_points = Math.floor(screen_w / 8);
                const color = colors[i];
                // if(signals.length < 2) return;
                for(i=1; i<signals.length; i++) {
                    const loc = (i - 1) * 8; 
                    const cur = scale(min, max, signals[i-1]); 
                    const next = scale(min, max, signals[i]);
                    drawPoint(loc, cur, next, color);
                }
                if(signals.length > max_points) scope.signals.shift();
            });

            function scale(min, max, signal) {
                let value = (signal - min) / (max - min);
                return screen_h * (1 - value);  
            }
            function drawPoint(loc, cur, next, color) {
                // check out-of-bound
                if(loc < 0 || loc > screen_w) return;
                if(cur < 0 || cur > screen_h) return;
                if(next < 0 || next > screen_h) return;
        
                screen.append('line')
                    .attr('x1', loc)
                    .attr('y1', cur)
                    .attr('x2', loc + 8)
                    .attr('y2', next)
                    .style("stroke", color)
                    .style("stroke-width", 2.5)
                    .style("opacity", .75);
            }
