    const cur_version = "1.5.1";  // __VERSION__;

    /**
     * return true if the version of Block Composer is same as recent version
     */
    function versionCheck() {
        if(getCookie("version") == cur_version) return true;
        else return false;
    }

    /**
     * fetch firmware data from Robomation DFU server.
     * @returns
     */
    async function fetchDFU() {
        const DFU = await fetch("https://dfu.roboid.org/api/product/final");  //  https://dfu.rbmation.com/finalJSON
        const json = await DFU.json();
        const data = [];
        json.forEach(js => {
            const { classification, service_uuid, product_id, device_id } = js;
            data.push({
                "classification": classification,
                "service_uuid": service_uuid,
                "product_id": product_id,
                "device_id": device_id,
            });
        });
        setCookie("DFU", JSON.stringify(data), 1);
    }

    /**
     * return true if the version of robot is not same as recent version
     * @param {*} dongle 
     * @returns 
     */

    function DFUCheck(dongle) { 
        if(!dongle.client) return;
        const { pid, version } = dongle.client;  // dongle.options

        const DFU = JSON.parse(getCookie("DFU"));
        let filtered_data = DFU.find(d => parseInt(d.product_id, 16) == pid);

        if(!filtered_data || version == parseInt(filtered_data.device_id, 16)) // In case DFU info does not contain robot or robot firmware is up to date.
            return false;
        else { // In case robot firmware is not up to date
            return true;
        } 
    }

    /**
     * return true if the version of dongle is not same as recent version
     * @param {*} dongle 
     * @returns 
     */

    function DongleCheck(dongle) { 
        if(!dongle.version) return false;
        const { protocol, major, minor, patch } = dongle.version;
        if(!protocol) return false;

        const DFU = JSON.parse(getCookie("DFU"));
        let filtered_data = DFU.find(d => parseInt(d.product_id, 16) == parseInt("0xF" + protocol.charAt(1), 16));
        let version = parseInt(filtered_data.device_id, 16).toString();
        if(!filtered_data || version == major + minor + patch) // In case DFU info does not contain dongle or dongle firmware is up to date.
            return false;
        else { // In case dongle firmware is not up to date
            return true;
        } 
    }

    /**
     * delete the old cached data about BlockComposer
     * @returns caches that old data about BlockComposer is deleted
     */
    function clearCache() {
        caches.keys().then(keyList => {
            return Promise.all(keyList.map(keys => {
                // if( keys.includes('rbmate.com') ) {
                    caches.open(keys).then(cache => {
                        cache.keys().then(key => {
                            key.forEach(k => {
                                if(k.url.includes("/BlockComposer")) {
                                    return cache.delete(k);
                                }
                            });
                        });
                    });
                    return caches;
                // }
            }))
        }).catch(e => {
            // console.log(e);
        }).finally(() => {
            setCookie("version", cur_version);
            window.location.reload();
        });
    }

