    function showExtensions() {
    	document.getElementById('extension_container').style.display = "block";
    }

    function hideExtensions() {
    	document.getElementById('extension_container').style.display = "none";
    }

    async function requestMic() {
    	try {
    		const permission = await navigator.permissions.query({ name: 'microphone' });
    		if (permission.state === 'granted' || permission.state === 'denied') return;
    		const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    		stream.getTracks().forEach(track => track.stop());
    	} catch(err) {
    		console.error(err);
    		return false;
    	}
    }

    async function requestCamera() {
    	try {
    		const permission = await navigator.permissions.query({ name: 'camera' });
    		if (permission.state === 'granted' || permission.state === 'denied') return;
    		const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    		stream.getTracks().forEach(track => track.stop());
    	} catch(err) {
    		console.error(err);
    		return false;
    	}
    }

